import Foundation

func maxPixelSize(pointWidth: Double, pointHeight: Double, scale: Double) -> Int {
    Int(max(pointWidth, pointHeight) * scale)
}

print(maxPixelSize(pointWidth: 60, pointHeight: 90, scale: 3))

struct CachedFormatter {
    static let buildCount: Int = {
        print("Built formatter once")
        return 1
    }()
}

var total = 0
for _ in 1...3 {
    total += CachedFormatter.buildCount
}
print("Reads: \(total)")

@concurrent
func filterPosts(_ items: [String]) async -> [String] {
    items.filter { $0.hasPrefix("Swift") }
}

@MainActor
final class TimelineVM {
    var visible: [String] = []
    func refresh() async {
        visible = await filterPosts(["Swift 6", "UIKit", "SwiftUI"])
        print(visible.count)
    }
}

await TimelineVM().refresh()

func hitchTimeRatio(hitchMs: Double, scrollSeconds: Double) -> Int {
    Int(hitchMs / scrollSeconds)
}

print("Ratio: \(hitchTimeRatio(hitchMs: 36, scrollSeconds: 3)) ms/s")

let delaysMs = [45, 120, 250, 410]
let formalHangs = delaysMs.filter { $0 >= 250 }
print("Noticeable: \(delaysMs.filter { $0 > 100 }.count), Hangs: \(formalHangs.count)")

final class UnsafelyShared {
    var count = 0
}

let box = UnsafelyShared()
Task.detached {
    print(box.count)
}
box.count += 1

