questions.modelAnswer:
import Foundation
import ImageIO

func thumbnailOptions(width: CGFloat, height: CGFloat, scale: CGFloat) -> [CFString: Any] {
    let maxPixels = max(width, height) * scale
    return [
        kCGImageSourceCreateThumbnailFromImageAlways: true,
        kCGImageSourceThumbnailMaxPixelSize: maxPixels,
        kCGImageSourceShouldCacheImmediately: true
    ]
}

let opts = thumbnailOptions(width: 50, height: 80, scale: 3)
let size = opts[kCGImageSourceThumbnailMaxPixelSize] as? CGFloat ?? 0
print(Int(size))

